const fs = require('fs');

// ═══════════════════════════════════════════════════════
//  CONFIGURAZIONE — modifica solo questa sezione
// ═══════════════════════════════════════════════════════

const OUTPUT_FOLDER  = 'C:/Users/arzig/OneDrive/Desktop/unrealkiara/img/generated';
const REF_IMAGE_PATH = 'C:/Users/arzig/OneDrive/Desktop/unrealkiara/img/ref-face-front.jpg';

// flux-dev  = qualità alta, img2img, ~€0.025/img
// flux-schnell = veloce, solo testo, ~€0.003/img (se non vuoi passare ref)
const MODEL = 'black-forest-labs/flux-dev';

// Quanto il prompt sovrascrive l'immagine di riferimento:
// 0.0 = uguale alla ref | 1.0 = solo testo, ignora ref
// Scena nuova con identità mantenuta → 0.68-0.78
const PROMPT_STRENGTH_DEFAULT = 0.72;

// ═══════════════════════════════════════════════════════
//  IDENTITÀ FISSA DI KIARA — sempre inclusa in ogni prompt
// ═══════════════════════════════════════════════════════

const IDENTITY = [
  'Kiara',
  'young Italian woman virtual fashion influencer',
  'warm olive skin',
  'dark chestnut hair flowing naturally',
  'delicate feminine features',
  'natural minimal makeup',
  'slim elegant build',
  'relaxed confident presence'
].join(', ');

const STYLE = [
  'minimalist Italian fashion editorial',
  'warm tones palette (ivory, peach, champagne, sand, cacao, coral)',
  'soft natural light',
  'photorealistic',
  'intimate diary mood',
  '1:1 square format'
].join(', ');

// ═══════════════════════════════════════════════════════
//  IMMAGINE DI RIFERIMENTO
// ═══════════════════════════════════════════════════════

let refImageBase64 = null;
try {
  const ext = REF_IMAGE_PATH.split('.').pop().toLowerCase();
  const mime = ext === 'png' ? 'image/png' : 'image/jpeg';
  const buf = fs.readFileSync(REF_IMAGE_PATH);
  refImageBase64 = `data:${mime};base64,${buf.toString('base64')}`;
  console.log('Ref image loaded:', REF_IMAGE_PATH);
} catch(e) {
  console.warn('Ref image not found — generating text-only:', e.message);
}

// ═══════════════════════════════════════════════════════
//  SCENE — solo la variabile per ogni immagine
//  Il blocco IDENTITY + STYLE viene preposto automaticamente
// ═══════════════════════════════════════════════════════

const scenes = [

  // ── RITUAL (mattina, routine) ──────────────────────
  { pillar:'ritual', slug:'morning-window',
    scene:'wearing ivory linen pajama set, holding white ceramic coffee cup, standing by large window, sheer curtains, warm morning light filtering through, Italian apartment' },

  { pillar:'ritual', slug:'coffee-hands',
    scene:'close-up, hands wrapped around ceramic mug, steaming coffee, wooden table, ivory linen cloth, morning light, peach warm tones, detail shot' },

  { pillar:'ritual', slug:'white-sheets',
    scene:'lying in white cotton sheets, peach morning light on bare shoulder, relaxed reading, warm minimal Italian apartment interior' },

  { pillar:'ritual', slug:'barefoot-floor',
    scene:'barefoot on warm wooden floor, ivory linen interior, soft morning sun rays through window, minimal Scandinavian Italian decor' },

  { pillar:'ritual', slug:'mirror-gaze',
    scene:'facing large mirror in minimal ivory bathroom, warm morning steam, calm expression, no makeup, raw morning ritual' },

  // ── WORLD (luoghi, momenti) ─────────────────────────
  { pillar:'world', slug:'cobblestone-walk',
    scene:'walking on cobblestone street, wide-leg sand linen trousers, tucked ivory blouse, warm afternoon Milan, blurred ochre background, candid editorial' },

  { pillar:'world', slug:'cafe-outdoor',
    scene:'sitting at marble outdoor cafe table, peach midi dress, cappuccino cup, dappled sunlight, Italian summer, candid lifestyle moment' },

  { pillar:'world', slug:'ochre-wall',
    scene:'leaning against warm ochre building wall, golden hour light, simple cream linen outfit, graphic shadow play, Italian city street style' },

  { pillar:'world', slug:'olive-trees',
    scene:'standing among olive trees, ivory and sage green linen dress, Mediterranean afternoon light, dreamy soft focus background, countryside Italy' },

  { pillar:'world', slug:'train-window',
    scene:'looking out train window, soft motion blur outside, warm interior light, champagne outfit, book in hand, contemplative expression' },

  { pillar:'world', slug:'flower-market',
    scene:'at outdoor flower market, ivory outfit, touching fresh peach flowers, warm natural light, candid lifestyle, Italian market atmosphere' },

  { pillar:'world', slug:'rooftop-sunset',
    scene:'on rooftop terrace at golden hour, flowing champagne dress, Italian city skyline soft focus below, warm sunset backlight' },

  // ── ARMADIO (outfit, moda) ──────────────────────────
  { pillar:'outfit', slug:'linen-sand-set',
    scene:'full length, wide-leg sand linen trousers, tucked ivory fitted top, minimal gold jewelry, clean warm studio, soft even light, fashion editorial pose' },

  { pillar:'outfit', slug:'slip-dress-champ',
    scene:'wearing champagne slip dress midi length, spaghetti straps, standing by natural window light, minimal white interior, editorial fashion' },

  { pillar:'outfit', slug:'cacao-blazer',
    scene:'wearing oversized cacao brown blazer over ivory blouse, against warm beige stone wall, editorial fashion, confident pose' },

  { pillar:'outfit', slug:'all-cream-layers',
    scene:'layered all-cream outfit, linen over cotton, various textures, movement shot, warm diffused studio light, clean background' },

  { pillar:'outfit', slug:'peach-trousers',
    scene:'wearing peach fitted crop top, wide-leg albicocca orange trousers, outdoor movement, hair in motion, warm afternoon light' },

  { pillar:'outfit', slug:'ivory-coat-winter',
    scene:'long ivory wool coat, winter editorial, stone architecture background, elegant minimal winter styling, cold clear day' },

  { pillar:'outfit', slug:'white-linen-dress',
    scene:'simple white linen dress, sun-drenched outdoor terrace, relaxed natural pose, warm Italian afternoon' },

  { pillar:'outfit', slug:'rust-knit-autumn',
    scene:'rust terracotta knit sweater, Italian countryside, golden autumn light, relaxed sitting on stone steps' },

  // ── MUSE (editoriale) ──────────────────────────────
  { pillar:'muse', slug:'studio-editorial',
    scene:'minimalist studio, ivory seamless background, avant-garde relaxed pose, high fashion editorial, Vogue Italia aesthetic, dramatic shadow' },

  { pillar:'muse', slug:'beauty-portrait',
    scene:'close-up portrait, bare skin, minimal makeup, warm side light, editorial beauty shot, direct eye contact, intimate' },

  { pillar:'muse', slug:'fabric-shadow',
    scene:'artistic fashion shot, ivory draped fabric, graphic shadow play on body, editorial mood, abstract minimal composition' },

  // ── SFONDI / TEXTURE (post Voce e Drop) ─────────────
  // Per i pillar texture prompt_strength alto → quasi solo testo
  { pillar:'texture', slug:'flatlay-ivory',
    scene:'flat lay overhead shot, ivory linen fabric, small pearl earring, white ceramic objects, champagne silk, warm morning light, no person, editorial product photography' },

  { pillar:'texture', slug:'warm-abstract',
    scene:'abstract warm texture background, ivory peach cream gradient tones, soft shadows, linen fabric detail, no person, perfect for text overlay, editorial' }

];

// ═══════════════════════════════════════════════════════
//  ASSEMBLY — componi i prompt completi
// ═══════════════════════════════════════════════════════

return scenes.map((s, i) => {
  const isTexture = s.pillar === 'texture';
  return { json: {
    index:          i + 1,
    total:          scenes.length,
    pillar:         s.pillar,
    slug:           s.slug,
    // Texture shots: solo testo (no identità persona)
    prompt:         isTexture
      ? `${s.scene}, ${STYLE}`
      : `${IDENTITY}, ${s.scene}, ${STYLE}`,
    refImageBase64: isTexture ? null : refImageBase64,
    promptStrength: isTexture ? 0.95 : PROMPT_STRENGTH_DEFAULT,
    filename:       `kiara-${s.pillar}-${s.slug}.webp`,
    outputFolder:   OUTPUT_FOLDER,
    model:          MODEL
  }};
});

