const res  = $input.first().json;
const meta = $('Loop').first().json;

if(res.status !== 'succeeded' || !res.output || !res.output[0]){
  // Se non è ancora done (raro con Prefer:wait), log e skip
  console.warn(`[${meta.slug}] status=${res.status} | ${JSON.stringify(res.error||'')}`);
  throw new Error(`Replicate error on ${meta.slug}: ${res.status}`);
}

console.log(`[${meta.index}/${meta.total}] ${meta.slug} → ${res.output[0]}`);

return [{ json: {
  ...meta,
  imageUrl:     res.output[0],
  predictionId: res.id
}}];

const total = $('Prompt List (25)').all().length;
const folder = $('Prompt List (25)').first().json.outputFolder;
console.log(`✅ Done: ${total} immagini Kiara salvate in ${folder}`);
return [{ json: { status:'done', count:total, folder } }];
